#include <chrono>
#include <iomanip>
#include <iostream>

#include "Halide.h"

// include common definitions
#include "defines.hpp"

// include benchmark-specific definitions
#include "deriche.hpp"

using num_t = DATA_TYPE;

using namespace Halide;

/**
 * Initialize alpha and imgIn.
 * imgIn and imgOut are Halide Buffers with dimensions (h, w),
 * and imgIn(j, i) corresponds to C's imgIn[i][j].
 */
static void init_array(int w,
                       int h,
                       num_t *alpha,
                       Halide::Buffer<num_t, 2> imgIn,
                       Halide::Buffer<num_t, 2> imgOut) {
    *alpha = (num_t)0.25; // parameter of the filter

    Var i("i"), j("j");
    Func init_imgIn("init_imgIn");
    // C code: imgIn[i][j] = ((313*i + 991*j) % 65536) / 65535.0f;
    // Buffer mapping: imgIn(j, i) == C's imgIn[i][j]
    init_imgIn(j, i) =
        cast<num_t>(((313 * i + 991 * j) % 65536)) / Expr((num_t)65535.0);

    init_imgIn.realize(imgIn);

    // imgOut is not initialized by the original C code prior to kernel use
    // (it is fully written before any read), so we can leave it as-is.
}

int main(int argc, char *argv[]) {
    // problem size
    int w = W;
    int h = H;

    // input data
    num_t alpha;

    // Buffers: first dimension is the C "j" index (0..h-1),
    // second dimension is the C "i" index (0..w-1).
    // So imgIn(j, i) corresponds to C's imgIn[i][j].
    Halide::Buffer<num_t, 2> imgIn(h, w);
    Halide::Buffer<num_t, 2> imgOut(h, w);
    Halide::Buffer<num_t, 2> y1(h, w);
    Halide::Buffer<num_t, 2> y2(h, w);

    // initialize data
    init_array(w, h, &alpha, imgIn, imgOut);

    // ---- Build Halide representation of the Deriche filter ----

    // Parameters
    Param<num_t> alpha_param("alpha");
    alpha_param.set(alpha);

    // Scalars derived from alpha, expressed as Halide Expr so they can
    // depend on the runtime parameter alpha_param.
    Expr one  = Expr((num_t)1.0);
    Expr two  = Expr((num_t)2.0);
    Expr mtwo = Expr((num_t)-2.0);

    Expr exp_neg_alpha    = exp(-alpha_param);
    Expr exp_neg_two_alpha = exp(mtwo * alpha_param);
    Expr exp_pos_two_alpha = exp(two * alpha_param);

    // k = (1 - e^-alpha)^2 / (1 + 2*alpha*e^-alpha - e^(2*alpha))
    Expr k_expr = (one - exp_neg_alpha) * (one - exp_neg_alpha) /
                  (one + two * alpha_param * exp_neg_alpha - exp_pos_two_alpha);

    Expr a1_expr = k_expr;
    Expr a2_expr = k_expr * exp_neg_alpha * (alpha_param - one);
    Expr a3_expr = k_expr * exp_neg_alpha * (alpha_param + one);
    Expr a4_expr = -k_expr * exp_neg_two_alpha;

    Expr a5_expr = a1_expr;
    Expr a6_expr = a2_expr;
    Expr a7_expr = a3_expr;
    Expr a8_expr = a4_expr;

    Expr b1_expr = pow(Expr((num_t)2.0), -alpha_param);
    Expr b2_expr = -exp_neg_two_alpha;

    Expr c1_expr = one;
    Expr c2_expr = one;

    // ImageParams for main images
    ImageParam imgIn_param(type_of<num_t>(), 2, "imgIn");
    ImageParam imgOut_param(type_of<num_t>(), 2, "imgOut");

    // ImageParams for intermediate y1, y2 (for combine stages)
    ImageParam y1_param(type_of<num_t>(), 2, "y1");
    ImageParam y2_param(type_of<num_t>(), 2, "y2");

    // State arrays for vertical forward pass (one state per column i)
    ImageParam xm1_col_param(type_of<num_t>(), 1, "xm1_col");
    ImageParam ym1_col_param(type_of<num_t>(), 1, "ym1_col");
    ImageParam ym2_col_param(type_of<num_t>(), 1, "ym2_col");

    // State arrays for vertical backward pass (one state per column i)
    ImageParam xp1_col_param(type_of<num_t>(), 1, "xp1_col");
    ImageParam xp2_col_param(type_of<num_t>(), 1, "xp2_col");
    ImageParam yp1_col_param(type_of<num_t>(), 1, "yp1_col");
    ImageParam yp2_col_param(type_of<num_t>(), 1, "yp2_col");

    // State arrays for horizontal forward pass (one state per row j)
    ImageParam tm1_row_param(type_of<num_t>(), 1, "tm1_row");
    ImageParam ym1_row_param(type_of<num_t>(), 1, "ym1_row");
    ImageParam ym2_row_param(type_of<num_t>(), 1, "ym2_row");

    // State arrays for horizontal backward pass (one state per row j)
    ImageParam tp1_row_param(type_of<num_t>(), 1, "tp1_row");
    ImageParam tp2_row_param(type_of<num_t>(), 1, "tp2_row");
    ImageParam yp1_row_param(type_of<num_t>(), 1, "yp1_row");
    ImageParam yp2_row_param(type_of<num_t>(), 1, "yp2_row");

    // Iteration indices for DP along rows and columns (host-driven)
    Param<int> j_param("j_param"); // current row index (0..h-1)
    Param<int> i_param("i_param"); // current column index (0..w-1)

    // ---- Vertical forward pass: y1 from imgIn ----
    //
    // C code:
    // for (i = 0; i < W; i++) {
    //   ym1 = ym2 = xm1 = 0;
    //   for (j = 0; j < H; j++) {
    //     y1[i][j] = a1*imgIn[i][j] + a2*xm1 + b1*ym1 + b2*ym2;
    //     xm1 = imgIn[i][j];
    //     ym2 = ym1;
    //     ym1 = y1[i][j];
    //   }
    // }
    //
    // We reorganize as:
    //   maintain state arrays xm1_col[i], ym1_col[i], ym2_col[i];
    //   for each j, compute y1[*, j] for all columns in parallel with Halide,
    //   then update xm1_col, ym1_col, ym2_col on host.

    Var col("col"); // column index (i in C)

    Func vert_fwd("vert_fwd");
    // Buffer mapping: imgIn_param(j_param, col) == C's imgIn[col][j_param]
    vert_fwd(col) =
        a1_expr * imgIn_param(j_param, col) +
        a2_expr * xm1_col_param(col) +
        b1_expr * ym1_col_param(col) +
        b2_expr * ym2_col_param(col);

    // ---- Vertical backward pass: y2 from imgIn ----
    //
    // C code:
    // for (i = 0; i < W; i++) {
    //   yp1 = yp2 = xp1 = xp2 = 0;
    //   for (j = H-1; j >= 0; j--) {
    //     y2[i][j] = a3*xp1 + a4*xp2 + b1*yp1 + b2*yp2;
    //     xp2 = xp1;
    //     xp1 = imgIn[i][j];
    //     yp2 = yp1;
    //     yp1 = y2[i][j];
    //   }
    // }
    Func vert_back("vert_back");
    vert_back(col) =
        a3_expr * xp1_col_param(col) +
        a4_expr * xp2_col_param(col) +
        b1_expr * yp1_col_param(col) +
        b2_expr * yp2_col_param(col);

    // ---- Combine vertical passes: imgOut = c1 * (y1 + y2) ----
    Var x("x"), y("y");
    Func combine_vert("combine_vert");
    combine_vert(x, y) = c1_expr * (y1_param(x, y) + y2_param(x, y));

    // ---- Horizontal forward pass: y1 from imgOut ----
    //
    // C code:
    // for (j = 0; j < H; j++) {
    //   tm1 = ym1 = ym2 = 0;
    //   for (i = 0; i < W; i++) {
    //     y1[i][j] = a5*imgOut[i][j] + a6*tm1 + b1*ym1 + b2*ym2;
    //     tm1 = imgOut[i][j];
    //     ym2 = ym1;
    //     ym1 = y1[i][j];
    //   }
    // }
    //
    // We reorganize as:
    //   maintain state arrays tm1_row[j], ym1_row[j], ym2_row[j];
    //   for each i, compute y1[i, *] for all rows in parallel with Halide,
    //   then update tm1_row, ym1_row, ym2_row on host.

    Var row("row"); // row index (j in C)

    Func horiz_fwd("horiz_fwd");
    // imgOut_param(row, i_param) == C's imgOut[i_param][row]
    horiz_fwd(row) =
        a5_expr * imgOut_param(row, i_param) +
        a6_expr * tm1_row_param(row) +
        b1_expr * ym1_row_param(row) +
        b2_expr * ym2_row_param(row);

    // ---- Horizontal backward pass: y2 from imgOut ----
    //
    // C code:
    // for (j = 0; j < H; j++) {
    //   tp1 = tp2 = yp1 = yp2 = 0;
    //   for (i = W-1; i >= 0; i--) {
    //     y2[i][j] = a7*tp1 + a8*tp2 + b1*yp1 + b2*yp2;
    //     tp2 = tp1;
    //     tp1 = imgOut[i][j];
    //     yp2 = yp1;
    //     yp1 = y2[i][j];
    //   }
    // }
    Func horiz_back("horiz_back");
    horiz_back(row) =
        a7_expr * tp1_row_param(row) +
        a8_expr * tp2_row_param(row) +
        b1_expr * yp1_row_param(row) +
        b2_expr * yp2_row_param(row);

    // ---- Final combine: imgOut = c2 * (y1 + y2) ----
    Func combine_horiz("combine_horiz");
    combine_horiz(x, y) = c2_expr * (y1_param(x, y) + y2_param(x, y));

    // (Optional) simple scheduling for the one-dimensional step funcs
    vert_fwd.vectorize(col, 8);
    vert_back.vectorize(col, 8);
    horiz_fwd.vectorize(row, 8);
    horiz_back.vectorize(row, 8);
    combine_vert.vectorize(x, 8);
    combine_horiz.vectorize(x, 8);

    // Bind ImageParams to underlying buffers
    imgIn_param.set(imgIn);
    imgOut_param.set(imgOut);

    y1_param.set(y1);
    y2_param.set(y2);

    // State buffers for vertical passes (per column i, size w)
    Halide::Buffer<num_t, 1> xm1_col(w), ym1_col(w), ym2_col(w);
    Halide::Buffer<num_t, 1> xp1_col(w), xp2_col(w), yp1_col(w), yp2_col(w);

    // Initialize vertical state buffers to zero
    for (int i = 0; i < w; i++) {
        xm1_col(i) = (num_t)0;
        ym1_col(i) = (num_t)0;
        ym2_col(i) = (num_t)0;

        xp1_col(i) = (num_t)0;
        xp2_col(i) = (num_t)0;
        yp1_col(i) = (num_t)0;
        yp2_col(i) = (num_t)0;
    }

    xm1_col_param.set(xm1_col);
    ym1_col_param.set(ym1_col);
    ym2_col_param.set(ym2_col);

    xp1_col_param.set(xp1_col);
    xp2_col_param.set(xp2_col);
    yp1_col_param.set(yp1_col);
    yp2_col_param.set(yp2_col);

    // State buffers for horizontal passes (per row j, size h)
    Halide::Buffer<num_t, 1> tm1_row(h), ym1_row(h), ym2_row(h);
    Halide::Buffer<num_t, 1> tp1_row(h), tp2_row(h), yp1_row(h), yp2_row(h);

    // Initialize horizontal state buffers to zero
    for (int j = 0; j < h; j++) {
        tm1_row(j) = (num_t)0;
        ym1_row(j) = (num_t)0;
        ym2_row(j) = (num_t)0;

        tp1_row(j) = (num_t)0;
        tp2_row(j) = (num_t)0;
        yp1_row(j) = (num_t)0;
        yp2_row(j) = (num_t)0;
    }

    tm1_row_param.set(tm1_row);
    ym1_row_param.set(ym1_row);
    ym2_row_param.set(ym2_row);

    tp1_row_param.set(tp1_row);
    tp2_row_param.set(tp2_row);
    yp1_row_param.set(yp1_row);
    yp2_row_param.set(yp2_row);

    // Compile all Halide Funcs ahead of timing
    vert_fwd.compile_jit();
    vert_back.compile_jit();
    horiz_fwd.compile_jit();
    horiz_back.compile_jit();
    combine_vert.compile_jit();
    combine_horiz.compile_jit();

    // Start timer (measure only the actual computation, not JIT time)
    auto start = std::chrono::high_resolution_clock::now();

    // ---- Execute Deriche filter ----

    // Temporary 1D buffers for step results
    Halide::Buffer<num_t, 1> line_col(w); // for vertical passes (over columns)
    Halide::Buffer<num_t, 1> line_row(h); // for horizontal passes (over rows)

    // Vertical forward pass: compute y1 from imgIn
    for (int j = 0; j < h; j++) {
        j_param.set(j);
        vert_fwd.realize(line_col);
        for (int i = 0; i < w; i++) {
            // y1(j, i) == C's y1[i][j]
            y1(j, i) = line_col(i);

            // update state for this column i
            xm1_col(i) = imgIn(j, i);
            ym2_col(i) = ym1_col(i);
            ym1_col(i) = y1(j, i);
        }
    }

    // Vertical backward pass: compute y2 from imgIn
    for (int j = h - 1; j >= 0; j--) {
        j_param.set(j);
        vert_back.realize(line_col);
        for (int i = 0; i < w; i++) {
            y2(j, i) = line_col(i);

            // update state for this column i
            xp2_col(i) = xp1_col(i);
            xp1_col(i) = imgIn(j, i);
            yp2_col(i) = yp1_col(i);
            yp1_col(i) = y2(j, i);
        }
    }

    // Combine vertical passes: imgOut = c1 * (y1 + y2)
    y1_param.set(y1);
    y2_param.set(y2);
    combine_vert.realize(imgOut);

    // Horizontal forward pass: compute y1 from imgOut
    for (int i = 0; i < w; i++) {
        i_param.set(i);
        horiz_fwd.realize(line_row);
        for (int j = 0; j < h; j++) {
            y1(j, i) = line_row(j);

            // update state for this row j
            tm1_row(j) = imgOut(j, i);
            ym2_row(j) = ym1_row(j);
            ym1_row(j) = y1(j, i);
        }
    }

    // Horizontal backward pass: compute y2 from imgOut
    for (int i = w - 1; i >= 0; i--) {
        i_param.set(i);
        horiz_back.realize(line_row);
        for (int j = 0; j < h; j++) {
            y2(j, i) = line_row(j);

            // update state for this row j
            tp2_row(j) = tp1_row(j);
            tp1_row(j) = imgOut(j, i);
            yp2_row(j) = yp1_row(j);
            yp1_row(j) = y2(j, i);
        }
    }

    // Final combine: imgOut = c2 * (y1 + y2)
    y1_param.set(y1);
    y2_param.set(y2);
    combine_horiz.realize(imgOut);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Print results to prevent dead-code elimination,
    // similar to PolyBench's print_array (but simplified).
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(6);
        for (int i = 0; i < w; i++) {
            for (int j = 0; j < h; j++) {
                // C's imgOut[i][j] == imgOut(j, i)
                std::cerr << imgOut(j, i) << '\n';
            }
        }
    }

    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
