```c++
#include <chrono>
#include <cmath>
#include <iomanip>
#include <iostream>
#include <string>

#include "Halide.h"

// include common definitions
#include "defines.hpp"

// include benchmark-specific definitions
#include "deriche.hpp"

using num_t = DATA_TYPE;

using namespace Halide;

static void init_array(int w,
                       int h,
                       num_t *alpha,
                       Halide::Buffer<num_t, 2> imgIn) {
    // Set filter parameter
    *alpha = (num_t)0.25;

    // imgIn is shape (h, w) and indexed as imgIn(j, i) to match C imgIn[i][j]
    Var i("i"), j("j");
    Func init_imgIn("init_imgIn");

    // Original C:
    // imgIn[i][j] = (DATA_TYPE) ((313*i+991*j)%65536) / 65535.0f;
    init_imgIn(j, i) = cast<num_t>(((313 * i + 991 * j) % 65536) / 65535.0f);

    init_imgIn.realize(imgIn);
}

int main(int argc, char *argv[]) {
    // Problem size
    int w = W;
    int h = H;

    // Input and output buffers (Halide layout: (j, i) <=> C layout: [i][j])
    Halide::Buffer<num_t, 2> imgIn(h, w);
    Halide::Buffer<num_t, 2> imgOut(h, w);

    // Filter parameter
    num_t alpha;

    // Initialize input
    init_array(w, h, &alpha, imgIn);

    // Wrap input buffer in an ImageParam so Halide Funcs can read it
    ImageParam imgIn_param(type_of<num_t>(), 2, "imgIn_param");
    imgIn_param.set(imgIn);

    // Precompute all scalar coefficients on the host, as in the original C code
    const num_t one = (num_t)1.0;
    const num_t two = (num_t)2.0;

    const num_t exp_neg_alpha   = std::exp(-alpha);
    const num_t exp_neg_2alpha  = std::exp(-two * alpha);
    const num_t exp_pos_2alpha  = std::exp(two * alpha);
    const num_t k = (one - exp_neg_alpha) * (one - exp_neg_alpha) /
                    (one + two * alpha * exp_neg_alpha - exp_pos_2alpha);

    const num_t a1 = k;
    const num_t a2 = k * exp_neg_alpha * (alpha - one);
    const num_t a3 = k * exp_neg_alpha * (alpha + one);
    const num_t a4 = -k * exp_neg_2alpha;
    const num_t a5 = a1;
    const num_t a6 = a2;
    const num_t a7 = a3;
    const num_t a8 = a4;

    const num_t b1 = (num_t)std::pow((num_t)2.0, -alpha);
    const num_t b2 = -exp_neg_2alpha;

    const num_t c1 = (num_t)1.0;
    const num_t c2 = (num_t)1.0;

    // Lift scalars into Halide Exprs
    Expr a1_e = a1, a2_e = a2, a3_e = a3, a4_e = a4;
    Expr a5_e = a5, a6_e = a6, a7_e = a7, a8_e = a8;
    Expr b1_e = b1, b2_e = b2;
    Expr c1_e = c1, c2_e = c2;

    // Vars: x == j (0..h-1), y == i (0..w-1)
    Var x("x"), y("y");

    // =========================
    // Vertical passes (columns)
    // =========================

    // Forward vertical IIR pass on imgIn -> y1_col
    // State tuple: (xm1, ym1, ym2, y_current)
    Func col_fwd_state("col_fwd_state");
    col_fwd_state(x, y) = Tuple(
        cast<num_t>(0), // xm1
        cast<num_t>(0), // ym1
        cast<num_t>(0), // ym2
        cast<num_t>(0)  // y_current
    );

    RDom r_col_fwd(0, h, "r_col_fwd");
    {
        Expr xm1_prev = col_fwd_state(r_col_fwd - 1, y)[0];
        Expr ym1_prev = col_fwd_state(r_col_fwd - 1, y)[1];
        Expr ym2_prev = col_fwd_state(r_col_fwd - 1, y)[2];

        Expr in_cur  = imgIn_param(r_col_fwd, y);
        Expr y_cur   = a1_e * in_cur + a2_e * xm1_prev +
                       b1_e * ym1_prev + b2_e * ym2_prev;
        Expr xm1_cur = in_cur;
        Expr ym2_cur = ym1_prev;
        Expr ym1_cur = y_cur;

        col_fwd_state(r_col_fwd, y) = Tuple(xm1_cur, ym1_cur, ym2_cur, y_cur);
    }

    Func y1_col("y1_col");
    y1_col(x, y) = col_fwd_state(x, y)[3];

    // Backward vertical IIR pass on imgIn -> y2_col
    // Implemented as forward scan on vertically-reversed image
    Func imgIn_rev_col("imgIn_rev_col");
    imgIn_rev_col(x, y) = imgIn_param(h - 1 - x, y);

    // State tuple: (xp1, xp2, yp1, yp2) where yp1 is the most recent output
    Func col_back_state("col_back_state");
    col_back_state(x, y) = Tuple(
        cast<num_t>(0), // xp1
        cast<num_t>(0), // xp2
        cast<num_t>(0), // yp1
        cast<num_t>(0)  // yp2
    );

    RDom r_col_back(0, h, "r_col_back");
    {
        Expr xp1_prev = col_back_state(r_col_back - 1, y)[0];
        Expr xp2_prev = col_back_state(r_col_back - 1, y)[1];
        Expr yp1_prev = col_back_state(r_col_back - 1, y)[2];
        Expr yp2_prev = col_back_state(r_col_back - 1, y)[3];

        Expr in_cur = imgIn_rev_col(r_col_back, y);

        Expr y_cur = a3_e * xp1_prev + a4_e * xp2_prev +
                     b1_e * yp1_prev + b2_e * yp2_prev;

        Expr xp2_cur = xp1_prev;
        Expr xp1_cur = in_cur;
        Expr yp2_cur = yp1_prev;
        Expr yp1_cur = y_cur;

        col_back_state(r_col_back, y) =
            Tuple(xp1_cur, xp2_cur, yp1_cur, yp2_cur);
    }

    Func y2_rev_col("y2_rev_col");
    // yp1 (component 2) is the current output
    y2_rev_col(x, y) = col_back_state(x, y)[2];

    Func y2_col("y2_col");
    // Undo the vertical reversal
    y2_col(x, y) = y2_rev_col(h - 1 - x, y);

    // Combine vertical passes: img1 = c1 * (y1_col + y2_col)
    Func img1("img1");
    img1(x, y) = c1_e * (y1_col(x, y) + y2_col(x, y));

    // =========================
    // Horizontal passes (rows)
    // =========================

    // Forward horizontal IIR pass on img1 -> y1_row
    // State tuple: (tm1, ym1, ym2, y_current)
    Func row_fwd_state("row_fwd_state");
    row_fwd_state(x, y) = Tuple(
        cast<num_t>(0), // tm1
        cast<num_t>(0), // ym1
        cast<num_t>(0), // ym2
        cast<num_t>(0)  // y_current
    );

    RDom r_row_fwd(0, w, "r_row_fwd");
    {
        Expr tm1_prev = row_fwd_state(x, r_row_fwd - 1)[0];
        Expr ym1_prev = row_fwd_state(x, r_row_fwd - 1)[1];
        Expr ym2_prev = row_fwd_state(x, r_row_fwd - 1)[2];

        Expr in_cur = img1(x, r_row_fwd);

        Expr y_cur = a5_e * in_cur + a6_e * tm1_prev +
                     b1_e * ym1_prev + b2_e * ym2_prev;

        Expr tm1_cur = in_cur;
        Expr ym2_cur = ym1_prev;
        Expr ym1_cur = y_cur;

        row_fwd_state(x, r_row_fwd) = Tuple(tm1_cur, ym1_cur, ym2_cur, y_cur);
    }

    Func y1_row("y1_row");
    y1_row(x, y) = row_fwd_state(x, y)[3];

    // Backward horizontal IIR pass on img1 -> y2_row
    // Implemented as forward scan on horizontally-reversed image
    Func img1_rev_row("img1_rev_row");
    img1_rev_row(x, y) = img1(x, w - 1 - y);

    // State tuple: (tp1, tp2, yp1, yp2) where yp1 is the most recent output
    Func row_back_state("row_back_state");
    row_back_state(x, y) = Tuple(
        cast<num_t>(0), // tp1
        cast<num_t>(0), // tp2
        cast<num_t>(0), // yp1
        cast<num_t>(0)  // yp2
    );

    RDom r_row_back(0, w, "r_row_back");
    {
        Expr tp1_prev = row_back_state(x, r_row_back - 1)[0];
        Expr tp2_prev = row_back_state(x, r_row_back - 1)[1];
        Expr yp1_prev = row_back_state(x, r_row_back - 1)[2];
        Expr yp2_prev = row_back_state(x, r_row_back - 1)[3];

        Expr in_cur = img1_rev_row(x, r_row_back);

        Expr y_cur = a7_e * tp1_prev + a8_e * tp2_prev +
                     b1_e * yp1_prev + b2_e * yp2_prev;

        Expr tp2_cur = tp1_prev;
        Expr tp1_cur = in_cur;
        Expr yp2_cur = yp1_prev;
        Expr yp1_cur = y_cur;

        row_back_state(x, r_row_back) =
            Tuple(tp1_cur, tp2_cur, yp1_cur, yp2_cur);
    }

    Func y2_rev_row("y2_rev_row");
    // yp1 (component 2) is the current output
    y2_rev_row(x, y) = row_back_state(x, y)[2];

    Func y2_row("y2_row");
    // Undo the horizontal reversal
    y2_row(x, y) = y2_rev_row(x, w - 1 - y);

    // Final output
    Func deriche("deriche");
    deriche(x, y) = c2_e * (y1_row(x, y) + y2_row(x, y));

    // Simple schedule: compute all the scanline state Funcs at root so each
    // recurrence is executed exactly once over the full domain.
    col_fwd_state.compute_root();
    col_back_state.compute_root();
    img1.compute_root();
    row_fwd_state.compute_root();
    row_back_state.compute_root();
    deriche.compute_root();

    // Compile the pipeline
    deriche.compile_jit();

    // Time just the execution
    auto start = std::chrono::high_resolution_clock::now();

    // Run kernel
    deriche.realize(imgOut);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally print the output (mainly to prevent dead-code elimination)
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(6);
        for (int i = 0; i < w; i++) {
            for (int j = 0; j < h; j++) {
                // imgOut(j, i) corresponds to C imgOut[i][j]
                std::cerr << imgOut(j, i) << '\n';
            }
        }
    }

    // Print timing (seconds)
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
