#include "deriche.hpp"

using num_t = DATA_TYPE;
using namespace Halide;

// Initialize imgIn with the same pattern as the C version.
// C code:
//
//   *alpha = 0.25;
//   for (i = 0; i < w; i++)
//     for (j = 0; j < h; j++)
//       imgIn[i][j] = ((313*i+991*j)%65536) / 65535.0f;
//
// Arrays in C are imgIn[i][j] with i in [0,w), j in [0,h).
// We map to Halide::Buffer(imgIn)(x=j, y=i), of shape (h, w).
static void init_array(int w, int h,
                       num_t *alpha,
                       Halide::Buffer<num_t, 2> imgIn,
                       Halide::Buffer<num_t, 2> imgOut) {
    (void)imgOut;  // Unused, kept for symmetry with original signature.

    *alpha = static_cast<num_t>(0.25);

    Var x("x"), y("y");
    Func init_imgIn("init_imgIn");

    // x corresponds to j (0..h-1), y corresponds to i (0..w-1).
    Expr i = y;
    Expr j = x;
    Expr val = (313 * i + 991 * j) % 65536;
    init_imgIn(x, y) = cast<num_t>(val) / cast<num_t>(65535.0f);

    init_imgIn.realize(imgIn);
}

int main(int argc, char *argv[]) {
    // Problem size.
    int w = W;
    int h = H;

    // Input/output images as Halide buffers.
    // We map C arrays img[W][H] as Buffer(h, w), accessed as img(j, i).
    Halide::Buffer<num_t, 2> imgIn(h, w);
    Halide::Buffer<num_t, 2> imgOut(h, w);
    Halide::Buffer<num_t, 2> y1(h, w);
    Halide::Buffer<num_t, 2> y2(h, w);

    // Scalar parameter.
    num_t alpha;

    // Initialize input data and alpha.
    init_array(w, h, &alpha, imgIn, imgOut);

    // Compute the Deriche filter coefficients on the host,
    // matching the original C code exactly:

    //   k  = (1 - exp(-alpha))^2 / (1 + 2*alpha*exp(-alpha) - exp(2*alpha));
    //   a1 = a5 = k;
    //   a2 = a6 = k*exp(-alpha)*(alpha-1);
    //   a3 = a7 = k*exp(-alpha)*(alpha+1);
    //   a4 = a8 = -k*exp(-2*alpha);
    //   b1 = pow(2, -alpha);
    //   b2 = -exp(-2*alpha);
    //   c1 = c2 = 1;
    const num_t one = static_cast<num_t>(1.0);
    const num_t two = static_cast<num_t>(2.0);

    num_t e_neg_alpha  = static_cast<num_t>(std::exp(-alpha));
    num_t e_neg_2alpha = static_cast<num_t>(std::exp(-two * alpha));

    num_t k = (one - e_neg_alpha) * (one - e_neg_alpha) /
              (one + two * alpha * e_neg_alpha -
               static_cast<num_t>(std::exp(two * alpha)));

    num_t a1, a2, a3, a4, a5, a6, a7, a8;
    num_t b1, b2, c1, c2;

    a1 = a5 = k;
    a2 = a6 = k * e_neg_alpha * (alpha - one);
    a3 = a7 = k * e_neg_alpha * (alpha + one);
    a4 = a8 = -k * e_neg_2alpha;
    b1 = static_cast<num_t>(std::pow(two, -alpha));
    b2 = -e_neg_2alpha;
    c1 = c2 = one;

    // -----------------------------------------------------------------------
    // Halide pipelines for the per-step transforms and combinations.
    // We follow translation rule 5: we express a single step of each
    // 1D recurrence as a pure Halide Func, and drive the recurrence
    // with host-side loops and buffers (double-buffer style).
    // -----------------------------------------------------------------------

    Target target = get_jit_target_from_environment();

    // Vars for 1D pipelines.
    Var row("row");  // index along width  (0..w-1)
    Var col("col");  // index along height (0..h-1)

    // ---------------- Vertical forward pass: along j (columns) ----------------
    //
    // Original C:
    //   for (i = 0; i < W; i++) {
    //     ym1 = ym2 = xm1 = 0;
    //     for (j = 0; j < H; j++) {
    //       y1[i][j] = a1*imgIn[i][j] + a2*xm1 + b1*ym1 + b2*ym2;
    //       xm1 = imgIn[i][j];
    //       ym2 = ym1;
    //       ym1 = y1[i][j];
    //     }
    //   }
    //
    // We treat the recurrence along j on the host. For each j we compute
    // y1(:, j) from the previous state arrays xm1, ym1, ym2, using a 1D
    // Halide Func over 'row' (i).

    ImageParam imgInParam(type_of<num_t>(), 2, "imgInParam");
    ImageParam xm1Param(type_of<num_t>(), 1, "xm1Param");
    ImageParam ym1Param(type_of<num_t>(), 1, "ym1Param");
    ImageParam ym2Param(type_of<num_t>(), 1, "ym2Param");
    Param<int> jParam("jParam");

    Func vertFwdStep("vertFwdStep");
    {
        Expr x_curr = imgInParam(jParam, row);  // imgIn[j][i]
        vertFwdStep(row) =
            cast<num_t>(a1) * x_curr +
            cast<num_t>(a2) * xm1Param(row) +
            cast<num_t>(b1) * ym1Param(row) +
            cast<num_t>(b2) * ym2Param(row);

        vertFwdStep.compute_root();
        vertFwdStep.compile_jit(target);
    }

    // ---------------- Vertical backward pass: along j (reverse) ---------------
    //
    // Original C:
    //   for (i = 0; i < W; i++) {
    //     yp1 = yp2 = xp1 = xp2 = 0;
    //     for (j = H-1; j >= 0; j--) {
    //       y2[i][j] = a3*xp1 + a4*xp2 + b1*yp1 + b2*yp2;
    //       xp2 = xp1;
    //       xp1 = imgIn[i][j];
    //       yp2 = yp1;
    //       yp1 = y2[i][j];
    //     }
    //   }

    ImageParam xp1Param(type_of<num_t>(), 1, "xp1Param");
    ImageParam xp2Param(type_of<num_t>(), 1, "xp2Param");
    ImageParam yp1Param(type_of<num_t>(), 1, "yp1Param");
    ImageParam yp2Param(type_of<num_t>(), 1, "yp2Param");
    Param<int> jBackParam("jBackParam");

    Func vertBackStep("vertBackStep");
    {
        // Note: inputs here are the previous-state arrays xp1, xp2, yp1, yp2.
        vertBackStep(row) =
            cast<num_t>(a3) * xp1Param(row) +
            cast<num_t>(a4) * xp2Param(row) +
            cast<num_t>(b1) * yp1Param(row) +
            cast<num_t>(b2) * yp2Param(row);

        vertBackStep.compute_root();
        vertBackStep.compile_jit(target);
    }

    // ---------------- Horizontal forward pass: along i (rows) -----------------
    //
    // Original C:
    //   for (j = 0; j < H; j++) {
    //     tm1 = ym1 = ym2 = 0;
    //     for (i = 0; i < W; i++) {
    //       y1[i][j] = a5*imgOut[i][j] + a6*tm1 + b1*ym1 + b2*ym2;
    //       tm1 = imgOut[i][j];
    //       ym2 = ym1;
    //       ym1 = y1[i][j];
    //     }
    //   }
    //
    // We again treat the recurrence on the host. For each i we compute
    // y1(i, :) over all j using a 1D Halide Func over 'col' (j).

    ImageParam imgOutParamF(type_of<num_t>(), 2, "imgOutParamF");
    ImageParam tm1Param(type_of<num_t>(), 1, "tm1Param");
    ImageParam h_ym1Param(type_of<num_t>(), 1, "h_ym1Param");
    ImageParam h_ym2Param(type_of<num_t>(), 1, "h_ym2Param");
    Param<int> iParamF("iParamF");

    Func horizFwdStep("horizFwdStep");
    {
        Expr x_curr = imgOutParamF(iParamF, col);  // imgOut[i][j]
        horizFwdStep(col) =
            cast<num_t>(a5) * x_curr +
            cast<num_t>(a6) * tm1Param(col) +
            cast<num_t>(b1) * h_ym1Param(col) +
            cast<num_t>(b2) * h_ym2Param(col);

        horizFwdStep.compute_root();
        horizFwdStep.compile_jit(target);
    }

    // ---------------- Horizontal backward pass: along i (reverse) -------------
    //
    // Original C:
    //   for (j = 0; j < H; j++) {
    //     tp1 = tp2 = yp1 = yp2 = 0;
    //     for (i = W-1; i >= 0; i--) {
    //       y2[i][j] = a7*tp1 + a8*tp2 + b1*yp1 + b2*yp2;
    //       tp2 = tp1;
    //       tp1 = imgOut[i][j];
    //       yp2 = yp1;
    //       yp1 = y2[i][j];
    //     }
    //   }

    ImageParam tp1Param(type_of<num_t>(), 1, "tp1Param");
    ImageParam tp2Param(type_of<num_t>(), 1, "tp2Param");
    ImageParam h_yp1Param(type_of<num_t>(), 1, "h_yp1Param");
    ImageParam h_yp2Param(type_of<num_t>(), 1, "h_yp2Param");
    Param<int> iParamB("iParamB");

    Func horizBackStep("horizBackStep");
    {
        horizBackStep(col) =
            cast<num_t>(a7) * tp1Param(col) +
            cast<num_t>(a8) * tp2Param(col) +
            cast<num_t>(b1) * h_yp1Param(col) +
            cast<num_t>(b2) * h_yp2Param(col);

        horizBackStep.compute_root();
        horizBackStep.compile_jit(target);
    }

    // ---------------- Combination passes: imgOut = c*(y1 + y2) ----------------

    ImageParam y1Param2D(type_of<num_t>(), 2, "y1Param2D");
    ImageParam y2Param2D(type_of<num_t>(), 2, "y2Param2D");
    Var x("x"), y("y");

    Func combine1("combine1");
    {
        combine1(x, y) = cast<num_t>(c1) * (y1Param2D(x, y) + y2Param2D(x, y));
        combine1.compute_root();
        combine1.compile_jit(target);
    }

    Func combine2("combine2");
    {
        combine2(x, y) = cast<num_t>(c2) * (y1Param2D(x, y) + y2Param2D(x, y));
        combine2.compute_root();
        combine2.compile_jit(target);
    }

    // Bind constant image parameters that don't change across iterations.
    imgInParam.set(imgIn);

    // -----------------------------------------------------------------------
    // Run the full Deriche filter, measuring only the filtering time.
    // -----------------------------------------------------------------------
    using clock = std::chrono::high_resolution_clock;
    auto start = clock::now();

    // -------- Vertical forward pass (fills y1) --------
    {
        Halide::Buffer<num_t> xm1_buf(w), ym1_buf(w), ym2_buf(w);
        Halide::Buffer<num_t> y1_row(w);

        // Initialize state to zero.
        for (int i = 0; i < w; i++) {
            xm1_buf(i) = static_cast<num_t>(0);
            ym1_buf(i) = static_cast<num_t>(0);
            ym2_buf(i) = static_cast<num_t>(0);
        }

        for (int j = 0; j < h; j++) {
            jParam.set(j);
            xm1Param.set(xm1_buf);
            ym1Param.set(ym1_buf);
            ym2Param.set(ym2_buf);

            vertFwdStep.realize(y1_row);

            // Store results and update state per column (i).
            for (int i = 0; i < w; i++) {
                y1(j, i) = y1_row(i);
            }
            for (int i = 0; i < w; i++) {
                xm1_buf(i) = imgIn(j, i);
                ym2_buf(i) = ym1_buf(i);
                ym1_buf(i) = y1_row(i);
            }
        }
    }

    // -------- Vertical backward pass (fills y2) --------
    {
        Halide::Buffer<num_t> xp1_buf(w), xp2_buf(w), yp1_buf(w), yp2_buf(w);
        Halide::Buffer<num_t> y2_row(w);

        // Initialize state to zero.
        for (int i = 0; i < w; i++) {
            xp1_buf(i) = static_cast<num_t>(0);
            xp2_buf(i) = static_cast<num_t>(0);
            yp1_buf(i) = static_cast<num_t>(0);
            yp2_buf(i) = static_cast<num_t>(0);
        }

        for (int j = h - 1; j >= 0; j--) {
            jBackParam.set(j);
            xp1Param.set(xp1_buf);
            xp2Param.set(xp2_buf);
            yp1Param.set(yp1_buf);
            yp2Param.set(yp2_buf);

            vertBackStep.realize(y2_row);

            // Store results for this column j.
            for (int i = 0; i < w; i++) {
                y2(j, i) = y2_row(i);
            }
            // Update state.
            for (int i = 0; i < w; i++) {
                xp2_buf(i) = xp1_buf(i);
                xp1_buf(i) = imgIn(j, i);
                yp2_buf(i) = yp1_buf(i);
                yp1_buf(i) = y2_row(i);
            }
        }
    }

    // -------- First combination: imgOut = c1 * (y1 + y2) --------
    {
        y1Param2D.set(y1);
        y2Param2D.set(y2);
        combine1.realize(imgOut);
    }

    // Bind imgOut for horizontal passes.
    imgOutParamF.set(imgOut);

    // -------- Horizontal forward pass (updates y1) --------
    {
        Halide::Buffer<num_t> tm1_buf(h), h_ym1_buf(h), h_ym2_buf(h);
        Halide::Buffer<num_t> y1_col(h);

        // Initialize state to zero.
        for (int j = 0; j < h; j++) {
            tm1_buf(j)   = static_cast<num_t>(0);
            h_ym1_buf(j) = static_cast<num_t>(0);
            h_ym2_buf(j) = static_cast<num_t>(0);
        }

        // Iterate over i (0..w-1), computing y1(i, :) per step.
        for (int i = 0; i < w; i++) {
            iParamF.set(i);
            tm1Param.set(tm1_buf);
            h_ym1Param.set(h_ym1_buf);
            h_ym2Param.set(h_ym2_buf);

            horizFwdStep.realize(y1_col);

            // Store results and update state per row (j).
            for (int j = 0; j < h; j++) {
                y1(j, i) = y1_col(j);
            }
            for (int j = 0; j < h; j++) {
                tm1_buf(j)   = imgOut(j, i);
                h_ym2_buf(j) = h_ym1_buf(j);
                h_ym1_buf(j) = y1_col(j);
            }
        }
    }

    // -------- Horizontal backward pass (updates y2) --------
    {
        Halide::Buffer<num_t> tp1_buf(h), tp2_buf(h), h_yp1_buf(h), h_yp2_buf(h);
        Halide::Buffer<num_t> y2_col(h);

        // Initialize state to zero.
        for (int j = 0; j < h; j++) {
            tp1_buf(j)   = static_cast<num_t>(0);
            tp2_buf(j)   = static_cast<num_t>(0);
            h_yp1_buf(j) = static_cast<num_t>(0);
            h_yp2_buf(j) = static_cast<num_t>(0);
        }

        for (int i = w - 1; i >= 0; i--) {
            iParamB.set(i);
            tp1Param.set(tp1_buf);
            tp2Param.set(tp2_buf);
            h_yp1Param.set(h_yp1_buf);
            h_yp2Param.set(h_yp2_buf);

            horizBackStep.realize(y2_col);

            // Store results for this column i.
            for (int j = 0; j < h; j++) {
                y2(j, i) = y2_col(j);
            }
            // Update state.
            for (int j = 0; j < h; j++) {
                tp2_buf(j)   = tp1_buf(j);
                tp1_buf(j)   = imgOut(j, i);
                h_yp2_buf(j) = h_yp1_buf(j);
                h_yp1_buf(j) = y2_col(j);
            }
        }
    }

    // -------- Final combination: imgOut = c2 * (y1 + y2) --------
    {
        y1Param2D.set(y1);
        y2Param2D.set(y2);
        combine2.realize(imgOut);
    }

    auto end = clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally print output to prevent dead-code elimination.
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(6);
        for (int i = 0; i < w; i++) {
            for (int j = 0; j < h; j++) {
                // Remember: Buffer(x=j, y=i)
                std::cerr << imgOut(j, i) << '\n';
            }
        }
    }

    // Print timing (seconds) to stdout.
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
