#include <chrono>
#include <cmath>
#include <iomanip>
#include <iostream>
#include <string>

#include "Halide.h"

// Common PolyBench-style definitions (DATA_TYPE, etc)
#include "defines.hpp"

// Benchmark-specific size definitions: W, H
#include "deriche.hpp"

using num_t = DATA_TYPE;

using namespace Halide;

// Initialize imgIn and imgOut similarly to the original C version.
static void init_array(int w,
                       int h,
                       num_t *alpha,
                       Halide::Buffer<num_t, 2> imgIn,
                       Halide::Buffer<num_t, 2> imgOut) {
    // C code: *alpha = 0.25;
    *alpha = (num_t)0.25;

    // C code:
    // for (i = 0; i < w; i++)
    //   for (j = 0; j < h; j++)
    //     imgIn[i][j] = ((313*i + 991*j) % 65536) / 65535.0f;

    // Our Buffers are laid out as imgIn(j, i) to match PolyBench's
    // [i][j] with j as the fast-varying dimension.
    Var i("i"), j("j");
    Func init_imgIn("init_imgIn"), init_imgOut("init_imgOut");

    Expr e = (313 * i + 991 * j) % 65536;
    init_imgIn(j, i) = cast<num_t>(e) / cast<num_t>(65535.0f);

    // imgOut is not read before being written in the kernel, but we
    // zero it for completeness.
    init_imgOut(j, i) = (num_t)0;

    init_imgIn.realize(imgIn);
    init_imgOut.realize(imgOut);
}

int main(int argc, char *argv[]) {
    // Problem size (width, height)
    int w = W;
    int h = H;

    // Buffers: we store as (y, x) = (j, i) to match PolyBench's [i][j].
    Halide::Buffer<num_t, 2> imgIn(h, w);
    Halide::Buffer<num_t, 2> imgOut(h, w);
    Halide::Buffer<num_t, 2> y1(h, w);
    Halide::Buffer<num_t, 2> y2(h, w);

    // Initialize arrays and alpha
    num_t alpha;
    init_array(w, h, &alpha, imgIn, imgOut);

    // ------------------------------------------------------------------
    // Compute Deriche filter coefficients (as in the C kernel)
    // ------------------------------------------------------------------
    // C code:
    // k = (1 - exp(-alpha))^2 / (1 + 2*alpha*exp(-alpha) - exp(2*alpha));
    // a1 = a5 = k;
    // a2 = a6 = k * exp(-alpha) * (alpha - 1);
    // a3 = a7 = k * exp(-alpha) * (alpha + 1);
    // a4 = a8 = -k * exp(-2*alpha);
    // b1 = pow(2.0, -alpha);
    // b2 = -exp(-2*alpha);
    // c1 = c2 = 1;

    num_t emalpha = std::exp(-alpha);
    num_t e2alpha = std::exp(static_cast<num_t>(2) * alpha);
    num_t em2alpha = std::exp(static_cast<num_t>(-2) * alpha);

    num_t k = ( (static_cast<num_t>(1) - emalpha) *
                (static_cast<num_t>(1) - emalpha) ) /
              ( static_cast<num_t>(1) +
                static_cast<num_t>(2) * alpha * emalpha -
                e2alpha );

    num_t a1 = k;
    num_t a2 = k * emalpha * (alpha - static_cast<num_t>(1));
    num_t a3 = k * emalpha * (alpha + static_cast<num_t>(1));
    num_t a4 = -k * em2alpha;

    num_t a5 = a1;
    num_t a6 = a2;
    num_t a7 = a3;
    num_t a8 = a4;

    num_t b1 = std::pow(static_cast<num_t>(2), -alpha);
    num_t b2 = -em2alpha;

    num_t c1 = static_cast<num_t>(1);
    num_t c2 = static_cast<num_t>(1);

    // ------------------------------------------------------------------
    // Halide parameters and step functions
    // ------------------------------------------------------------------

    // Common scalar Params
    Param<num_t> a1_p("a1"), a2_p("a2"), a3_p("a3"), a4_p("a4");
    Param<num_t> a5_p("a5"), a6_p("a6"), a7_p("a7"), a8_p("a8");
    Param<num_t> b1_p("b1"), b2_p("b2");
    Param<num_t> c1_p("c1"), c2_p("c2");

    a1_p.set(a1);
    a2_p.set(a2);
    a3_p.set(a3);
    a4_p.set(a4);
    a5_p.set(a5);
    a6_p.set(a6);
    a7_p.set(a7);
    a8_p.set(a8);
    b1_p.set(b1);
    b2_p.set(b2);
    c1_p.set(c1);
    c2_p.set(c2);

    // ImageParam for the full input image (y, x) == (j, i).
    ImageParam imgIn_p(type_of<num_t>(), 2, "imgIn_p");
    imgIn_p.set(imgIn);

    // ImageParam for the intermediate (and final) output image.
    ImageParam imgOut_p(type_of<num_t>(), 2, "imgOut_p");
    imgOut_p.set(imgOut);

    // 1D state arrays for horizontal forward pass (along j, per column i).
    ImageParam y_prev_p(type_of<num_t>(), 1, "y_prev_p");
    ImageParam y_prev2_p(type_of<num_t>(), 1, "y_prev2_p");
    Param<int> j_p("j_p");  // current row index (j) for horizontal passes

    // Horizontal forward step:
    //
    // For j >= 1:
    //   y1[i][j] = a1 * imgIn[i][j] +
    //              a2 * imgIn[i][j-1] +
    //              b1 * y1[i][j-1] +
    //              b2 * y1[i][j-2];
    //
    // In Halide coordinates: y1(j, i), imgIn(j, i)
    // State arrays y_prev(i) = y1(i, j-1), y_prev2(i) = y1(i, j-2).
    Var idx("idx");
    Func horiz_fwd("horiz_fwd");
    horiz_fwd(idx) =
        a1_p * imgIn_p(j_p, idx) +
        a2_p * imgIn_p(j_p - 1, idx) +
        b1_p * y_prev_p(idx) +
        b2_p * y_prev2_p(idx);
    horiz_fwd.vectorize(idx, 8);

    // Horizontal backward pass state arrays: xp1, xp2, yp1, yp2; all per column i.
    ImageParam xp1_p(type_of<num_t>(), 1, "xp1_p");
    ImageParam xp2_p(type_of<num_t>(), 1, "xp2_p");
    ImageParam yp1_p(type_of<num_t>(), 1, "yp1_p");
    ImageParam yp2_p(type_of<num_t>(), 1, "yp2_p");

    // Horizontal backward step:
    //
    // y2[i][j] = a3 * xp1 + a4 * xp2 + b1 * yp1 + b2 * yp2;
    //
    // xp1, xp2, yp1, yp2 are per-column state arrays.
    Func horiz_back("horiz_back");
    horiz_back(idx) =
        a3_p * xp1_p(idx) +
        a4_p * xp2_p(idx) +
        b1_p * yp1_p(idx) +
        b2_p * yp2_p(idx);
    horiz_back.vectorize(idx, 8);

    // Vertical forward pass, scanning along i (columns), with state per row j.
    ImageParam v_prev_p(type_of<num_t>(), 1, "v_prev_p");
    ImageParam v_prev2_p(type_of<num_t>(), 1, "v_prev2_p");
    Param<int> i_p("i_p");  // current column index (i) for vertical passes
    Var idy("idy");

    // Vertical forward step:
    //
    // For i >= 1:
    //   y1[i][j] = a5 * imgOut[i][j] +
    //              a6 * imgOut[i-1][j] +
    //              b1 * y1[i-1][j] +
    //              b2 * y1[i-2][j];
    //
    // In Halide coordinates: y1(j, i), imgOut(j, i)
    // State arrays v_prev(j) = y1(j, i-1), v_prev2(j) = y1(j, i-2).
    Func vert_fwd("vert_fwd");
    vert_fwd(idy) =
        a5_p * imgOut_p(idy, i_p) +
        a6_p * imgOut_p(idy, i_p - 1) +
        b1_p * v_prev_p(idy) +
        b2_p * v_prev2_p(idy);
    vert_fwd.vectorize(idy, 8);

    // Vertical backward pass state arrays: vx1, vx2, vy1, vy2; all per row j.
    ImageParam vx1_p(type_of<num_t>(), 1, "vx1_p");
    ImageParam vx2_p(type_of<num_t>(), 1, "vx2_p");
    ImageParam vy1_p(type_of<num_t>(), 1, "vy1_p");
    ImageParam vy2_p(type_of<num_t>(), 1, "vy2_p");

    // Vertical backward step:
    //
    // y2[i][j] = a7 * tp1 + a8 * tp2 + b1 * yp1 + b2 * yp2;
    //
    // tp1, tp2, yp1, yp2 become vx1, vx2, vy1, vy2 (per row j).
    Func vert_back("vert_back");
    vert_back(idy) =
        a7_p * vx1_p(idy) +
        a8_p * vx2_p(idy) +
        b1_p * vy1_p(idy) +
        b2_p * vy2_p(idy);
    vert_back.vectorize(idy, 8);

    // Combination stages: imgOut = c1 * (y1 + y2) and imgOut = c2 * (y1 + y2)
    ImageParam y1_p(type_of<num_t>(), 2, "y1_p");
    ImageParam y2_p(type_of<num_t>(), 2, "y2_p");
    y1_p.set(y1);
    y2_p.set(y2);

    Var x("x"), y("y");
    Func combine1("combine1");
    combine1(y, x) = c1_p * (y1_p(y, x) + y2_p(y, x));
    combine1.vectorize(x, 8);

    Func combine2("combine2");
    combine2(y, x) = c2_p * (y1_p(y, x) + y2_p(y, x));
    combine2.vectorize(x, 8);

    // Compile all step functions ahead-of-time for JIT
    horiz_fwd.compile_jit();
    horiz_back.compile_jit();
    vert_fwd.compile_jit();
    vert_back.compile_jit();
    combine1.compile_jit();
    combine2.compile_jit();

    // ------------------------------------------------------------------
    // Run the deriche kernel and time it
    // ------------------------------------------------------------------

    auto start = std::chrono::high_resolution_clock::now();

    // ---------- Horizontal passes (along j) ----------

    // State arrays along i (columns)
    Halide::Buffer<num_t, 1> y_prev(w), y_prev2(w), col_tmp(w);
    y_prev.fill((num_t)0);
    y_prev2.fill((num_t)0);

    // 1) Forward pass in j (increasing j)
    //
    // j = 0 is a special case:
    //   ym1 = ym2 = xm1 = 0
    //   y1[i][0] = a1 * imgIn[i][0]
    for (int i = 0; i < w; i++) {
        num_t val = a1 * imgIn(0, i);
        y1(0, i) = val;
        y_prev(i) = val;
        y_prev2(i) = (num_t)0;
    }

    // Now process j = 1 .. h-1 with the Halide step function.
    y_prev_p.set(y_prev);
    y_prev2_p.set(y_prev2);
    for (int j = 1; j < h; j++) {
        j_p.set(j);
        // Make sure the ImageParams see the current state buffers.
        y_prev_p.set(y_prev);
        y_prev2_p.set(y_prev2);

        horiz_fwd.realize(col_tmp);

        // Store results into the 2D y1 buffer and update state.
        for (int i = 0; i < w; i++) {
            num_t val = col_tmp(i);
            y1(j, i) = val;

            // Update states for next j
            y_prev2(i) = y_prev(i);
            y_prev(i) = val;
        }
    }

    // 2) Backward pass in j (decreasing j)
    //
    // State arrays per column i: xp1, xp2, yp1, yp2
    Halide::Buffer<num_t, 1> xp1(w), xp2(w), yp1_(w), yp2_(w);
    xp1.fill((num_t)0);
    xp2.fill((num_t)0);
    yp1_.fill((num_t)0);
    yp2_.fill((num_t)0);

    xp1_p.set(xp1);
    xp2_p.set(xp2);
    yp1_p.set(yp1_);
    yp2_p.set(yp2_);

    for (int j = h - 1; j >= 0; j--) {
        // Set current state
        xp1_p.set(xp1);
        xp2_p.set(xp2);
        yp1_p.set(yp1_);
        yp2_p.set(yp2_);

        horiz_back.realize(col_tmp);

        // Store results to y2 and update state arrays for next j
        for (int i = 0; i < w; i++) {
            num_t val = col_tmp(i);
            y2(j, i) = val;

            num_t old_xp1 = xp1(i);
            num_t old_yp1 = yp1_(i);

            xp2(i) = old_xp1;
            xp1(i) = imgIn(j, i);

            yp2_(i) = old_yp1;
            yp1_(i) = val;
        }
    }

    // ---------- First combination: imgOut = c1 * (y1 + y2) ----------
    combine1.realize(imgOut);
    // imgOut_p was set to imgOut earlier; content has changed but
    // ImageParam still points to the same buffer.

    // ---------- Vertical passes (along i) ----------

    // Vertical forward pass state arrays, per row j
    Halide::Buffer<num_t, 1> v_prev(h), v_prev2(h), row_tmp(h);
    v_prev.fill((num_t)0);
    v_prev2.fill((num_t)0);

    // 3) Forward pass in i (increasing i)
    //
    // i = 0 special case:
    //   tm1 = ym1 = ym2 = 0
    //   y1[0][j] = a5 * imgOut[0][j]
    for (int j = 0; j < h; j++) {
        num_t val = a5 * imgOut(j, 0);
        y1(j, 0) = val;
        v_prev(j) = val;
        v_prev2(j) = (num_t)0;
    }

    imgOut_p.set(imgOut);
    v_prev_p.set(v_prev);
    v_prev2_p.set(v_prev2);

    for (int i = 1; i < w; i++) {
        i_p.set(i);
        v_prev_p.set(v_prev);
        v_prev2_p.set(v_prev2);

        vert_fwd.realize(row_tmp);

        // Store results into y1 and update vertical state
        for (int j = 0; j < h; j++) {
            num_t val = row_tmp(j);
            y1(j, i) = val;

            num_t old_v_prev = v_prev(j);
            v_prev2(j) = old_v_prev;
            v_prev(j) = val;
        }
    }

    // 4) Backward pass in i (decreasing i)
    //
    // State arrays per row j: vx1, vx2, vy1, vy2
    Halide::Buffer<num_t, 1> vx1(h), vx2(h), vy1(h), vy2(h);
    vx1.fill((num_t)0);
    vx2.fill((num_t)0);
    vy1.fill((num_t)0);
    vy2.fill((num_t)0);

    vx1_p.set(vx1);
    vx2_p.set(vx2);
    vy1_p.set(vy1);
    vy2_p.set(vy2);

    for (int i = w - 1; i >= 0; i--) {
        vx1_p.set(vx1);
        vx2_p.set(vx2);
        vy1_p.set(vy1);
        vy2_p.set(vy2);

        vert_back.realize(row_tmp);

        // Store to y2 and update state arrays
        for (int j = 0; j < h; j++) {
            num_t val = row_tmp(j);
            y2(j, i) = val;

            num_t old_vx1 = vx1(j);
            num_t old_vy1 = vy1(j);

            vx2(j) = old_vx1;
            vx1(j) = imgOut(j, i);

            vy2(j) = old_vy1;
            vy1(j) = val;
        }
    }

    // ---------- Final combination: imgOut = c2 * (y1 + y2) ----------
    combine2.realize(imgOut);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // ------------------------------------------------------------------
    // Print results (to prevent dead-code elimination) and timing
    // ------------------------------------------------------------------
    using namespace std::string_literals;

    // Print imgOut in the same logical order as the C code: imgOut[i][j]
    // which corresponds to imgOut(j, i) in our Buffer.
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(6);
        for (int i = 0; i < w; i++) {
            for (int j = 0; j < h; j++) {
                std::cerr << imgOut(j, i) << '\n';
            }
        }
    }

    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
